export const importContentItems = (
  projectId: string,
  key: string,
  importContentItemsCommand: ImportContentItemsCommand,
  signal?: AbortSignal,
) => {
  return customInstance<ImportContentItemsResult>({
    url: `/api/projects/${projectId}/content-types/${key}/contents/import`,
    method: "POST",
    headers: { "Content-Type": "application/json" },
    data: importContentItemsCommand,
    signal,
  });
};

export const getImportContentItemsMutationOptions = <
  TError = ErrorResponse | void,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof importContentItems>>,
    TError,
    { projectId: string; key: string; data: ImportContentItemsCommand },
    TContext
  >;
}): UseMutationOptions<
  Awaited<ReturnType<typeof importContentItems>>,
  TError,
  { projectId: string; key: string; data: ImportContentItemsCommand },
  TContext
> => {
  const mutationKey = ["importContentItems"];
  const { mutation: mutationOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey } };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof importContentItems>>,
    { projectId: string; key: string; data: ImportContentItemsCommand }
  > = (props) => {
    const { projectId, key, data } = props ?? {};

    return importContentItems(projectId, key, data);
  };

  return { mutationFn, ...mutationOptions };
};

